package cn.edu.njupt.studycheckin;

import android.content.Context;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;

final class AutomaticEvaluationTests {
    private static JSONObject entry(Object minutes,Object learned,Object reviewed)throws Exception{return new JSONObject().put("minutes",minutes).put("newWords",learned).put("reviewWords",reviewed).put("content","").put("problem","").put("forgotWords","");}
    private static void check(List<String> passes,boolean ok,String label)throws Exception{if(!ok)throw new Exception("FAIL: "+label);passes.add(label);}
    static void run(Context context,List<String> passes)throws Exception{
        JSONArray cases=new JSONArray(DataStore.readText(context.getAssets().open("automatic-assessment-cases.json"))),results=new JSONArray();
        for(int i=0;i<cases.length();i++){
            JSONObject c=cases.getJSONObject(i),result=Evaluation.evaluateDay(c.getJSONObject("basis"),c.isNull("record")?null:c.getJSONObject("record"),c.getLong("recordRevision"),c.getString("phase"),null),expected=c.getJSONObject("expected");
            for(java.util.Iterator<String> it=expected.keys();it.hasNext();){String key=it.next();Object value=result.opt(key);if(key.equals("timeLevel")){JSONArray items=result.getJSONArray("items");for(int j=0;j<items.length();j++)if(items.getJSONObject(j).getString("id").equals("total-time"))value=items.getJSONObject(j).get("level");}check(passes,Evaluation.same(value,expected.get(key)),"automatic "+c.getString("name")+" / "+key);}
            results.put(new JSONObject().put("name",c.getString("name")).put("result",result));
        }
        File file=new File(context.getCacheDir(),"automatic-java-results.json");try(FileOutputStream out=new FileOutputStream(file)){out.write(results.toString().getBytes(StandardCharsets.UTF_8));}
        JSONObject state=DataStore.migrateState(new JSONObject(DataStore.readText(context.getAssets().open("seed.json"))));state.remove("evaluation");JSONObject plan=state.getJSONObject("plan");JSONArray defaults=new JSONArray();for(int i=0;i<7;i++)defaults.put(new JSONObject().put("min",60).put("max",120));JSONArray zero=new JSONArray();for(int i=0;i<7;i++)zero.put(0);
        plan.put("startDate","2026-10-26").put("endDate","2026-11-02").put("targets",new JSONObject()).put("subjects",new JSONArray().put(new JSONObject().put("id","math").put("name","高数").put("kind","math").put("defaults",defaults)).put(new JSONObject().put("id","vocab").put("name","单词").put("kind","vocab").put("wordGoal",0).put("defaults",zero)));
        state.put("records",new JSONObject()).put("assessmentBases",new JSONObject());Evaluation.Clock clock=new Evaluation.Clock("2026-10-25","2026-10-25T04:00:00.000Z","Asia/Shanghai");Evaluation.initialize(state,clock);Evaluation.validate(state);
        JSONObject next=new JSONObject(state.toString()),before=new JSONObject(state.getJSONObject("evaluation").getJSONObject("bases").getJSONObject("2026-10-27").toString());next.getJSONObject("plan").getJSONObject("targets").put("2026-10-27",new JSONObject().put("math",new JSONObject().put("min",10).put("max",20)));Evaluation.reconcile(state,next,new Evaluation.Clock("2026-10-27","2026-10-27T04:00:00.000Z","Asia/Shanghai"));
        check(passes,Evaluation.same(before,next.getJSONObject("evaluation").getJSONObject("bases").getJSONObject("2026-10-27")),"automatic native same-day target reduction retains the fixed basis");
        state=Evaluation.scheduleChange(state,new JSONObject().put("from","2026-10-26").put("scope","date").put("date","2026-11-01").put("config",Evaluation.defaultConfig("rest")),clock);
        for(int i=0;i<4;i++){String date=java.time.LocalDate.parse("2026-10-26").plusDays(i).toString();state.getJSONObject("records").put(date,new JSONObject().put("subjects",new JSONObject().put("math",entry(i==3?40:90,JSONObject.NULL,JSONObject.NULL)).put("vocab",entry(JSONObject.NULL,0,0))).put("status",JSONObject.NULL).put("restKept",JSONObject.NULL).put("note",""));}
        JSONObject stats=Evaluation.statistics(state,"2026-10-26","2026-11-01","2026-11-02");check(passes,stats.getInt("D")==6&&stats.getInt("C")==4&&stats.getInt("P")==3&&stats.getDouble("rate")==50&&stats.getDouble("coverage")==66.7&&stats.getDouble("conditional")==75,"automatic native D6 C4 P3 uses all ended obligations and coverage");
        check(passes,Evaluation.statistics(state,"2026-10-26","2026-11-02","2026-10-27").getInt("D")==1,"automatic native current and future days stay outside the completed-day denominator");
        JSONObject earlier=Evaluation.scheduleChange(state,new JSONObject().put("from","2026-10-26").put("scope","weekly").put("weekday",1).put("config",Evaluation.defaultConfig("review").put("reviewMin",45).put("reviewMax",60).put("reviewWords",80)),clock);
        check(passes,Evaluation.resolve(earlier.getJSONObject("evaluation"),"2026-11-01").getJSONObject("config").getString("type").equals("rest")&&Evaluation.resolve(earlier.getJSONObject("evaluation"),"2026-10-27").getJSONObject("config").getString("type").equals("review"),"automatic native earlier future edits retain later explicit dates");
        JSONObject sourceState=new JSONObject(state.toString()),daily=sourceState.getJSONObject("records").getJSONObject("2026-10-26"),entry=daily.getJSONObject("subjects").getJSONObject("math");entry.put("minutes",10);JSONObject session=new JSONObject().put("id","dedup-auto").put("date","2026-10-26").put("subjectId","math").put("seconds",1800).put("endedAt","2026-10-26T05:00:00Z");sourceState.put("sessions",new JSONArray().put(session));daily.put("sessions",new JSONArray().put(new JSONObject(session.toString())));
        check(passes,Evaluation.timerTotals(sourceState,"2026-10-26").getDouble("math")==1800&&Evaluation.assess(sourceState,"2026-10-26","2026-10-27").getString("recordState").equals("需核对"),"automatic native deduplicates sources and surfaces contradictory manual totals");
        daily.put("timeCorrections",new JSONObject().put("math",new JSONObject().put("minutes",10).put("timerSeconds",1800).put("at","2026-10-26T05:01:00.000Z")));check(passes,Evaluation.timeConflicts(sourceState,"2026-10-26").length()==0,"automatic native explicit time correction resolves the known source contradiction");
        JSONObject invalid=new JSONObject(state.toString());invalid.getJSONObject("evaluation").getJSONObject("bases").getJSONObject("2026-10-26").put("dayType","rest");boolean rejected=false;try{Evaluation.validate(invalid);}catch(Exception expected){rejected=true;}check(passes,rejected,"automatic native rejects rest identity with required goals before restore");
        String original=DataStore.load(context).toString();try{DataStore.restore(context,sourceState);JSONObject saved=DataStore.load(context);check(passes,Evaluation.same(saved.getJSONObject("evaluation"),sourceState.getJSONObject("evaluation")),"automatic native JSON restore preserves fixed bases and schedule ledger exactly");java.io.ByteArrayOutputStream zip=new java.io.ByteArrayOutputStream();BackupManager.export(context,zip);try(BackupManager.Imported imported=BackupManager.read(context,new java.io.ByteArrayInputStream(zip.toByteArray()))){check(passes,Evaluation.same(imported.study.getJSONObject("evaluation"),saved.getJSONObject("evaluation")),"automatic native complete ZIP roundtrip retains schema9 automatic criteria");}java.io.ByteArrayOutputStream csv=new java.io.ByteArrayOutputStream();ReportExport.write(context,saved,csv,"csv","2026-10-26","2026-11-01","all");String text=new String(csv.toByteArray(),StandardCharsets.UTF_8);check(passes,text.contains("全天目标结果")&&text.contains("自动评估统计")&&text.contains("原计划必达与参考")&&text.contains("记录完整率%"),"automatic native CSV carries overall goals, fixed basis and complete denominator statistics");java.io.File sample=new java.io.File(context.getCacheDir(),"automatic-assessment-sample.pdf");try(java.io.FileOutputStream out=new java.io.FileOutputStream(sample)){ReportExport.write(context,saved,out,"pdf","2026-10-26","2026-11-01","all");}try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(context.getCacheDir(),"automatic-assessment-sample.csv"))){out.write(csv.toByteArray());}try(android.os.ParcelFileDescriptor descriptor=android.os.ParcelFileDescriptor.open(sample,android.os.ParcelFileDescriptor.MODE_READ_ONLY);android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(descriptor)){check(passes,renderer.getPageCount()>0,"automatic native PDF opens in the real Android renderer with new summary and goal fields");}}finally{DataStore.restore(context,new JSONObject(original));}

    }
}
